PREFIX mex: <https://example.org/mex-ontologi/vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?dataset (COUNT(?c) AS ?revisadas) WHERE {
  ?c a mex:CorrespondenciaSemantica ;
     mex:estadoCorrespondencia "documental_revisada" ;
     rdfs:label ?lab .
  BIND(STRAFTER(STR(?lab), "— ") AS ?dataset)
} GROUP BY ?dataset ORDER BY DESC(?revisadas) LIMIT 100

PREFIX mex: <https://example.org/mex-ontologi/vocab/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?lab ?ev ?estado WHERE {
  ?c a mex:CorrespondenciaSemantica ;
     rdfs:label ?lab ;
     mex:evidenciaTextual ?ev ;
     mex:estadoCorrespondencia ?estado .
  FILTER(CONTAINS(?lab, "Ganadería Sonora") || CONTAINS(?lab, "Censo Ganadero") || CONTAINS(?lab, "Subastas Ganadera"))
} ORDER BY ?lab ?ev LIMIT 2000
